    /** Instrumentation.newActivity calls this hook; a token alone cannot create a QA activity. */
    static Activity newActivityIfRequested(String className,Intent intent){
        Session session=active;if(!MainActivity.class.getName().equals(className)||intent==null||!intent.hasExtra(EXTRA))return null;
        if(session==null||!session.token.equals(intent.getStringExtra(EXTRA)))throw new IllegalStateException("QA_UI_FIXTURE_TOKEN_REQUIRED");
        QaMainActivity activity=new QaMainActivity();activity.session=session;return activity;
    }

    /** Same registered Activity/window and production lifecycle, isolated before onCreate. */
    public static final class QaMainActivity extends MainActivity {
        private Session session;
        @Override protected void attachBaseContext(Context base){if(session==null)throw new IllegalStateException("QA_UI_CONTEXT_REQUIRED");super.attachBaseContext(session.context);}
        @Override protected void onCreate(Bundle saved){
            super.onCreate(saved);
            try{
                if(!getFilesDir().getCanonicalPath().contains(session.fixture.context.prefix)||getApplicationContext()!=session.context)throw new IllegalStateException("QA_UI_CONTEXT_NOT_ISOLATED");
                // Main's platform status reader must observe the very same QA boot/clock.
                // Otherwise a genuine status read would latch a false device-restart review.
                Field storeField=MainActivity.class.getDeclaredField("store");storeField.setAccessible(true);PixelLocalStore mainStore=(PixelLocalStore)storeField.get(this);Field clockField=PixelLocalStore.class.getDeclaredField("clock");clockField.setAccessible(true);clockField.set(mainStore,session.clock);if(clockField.get(mainStore)!=session.clock)throw new IllegalStateException("QA_UI_CLOCK_NOT_BOUND");
                Field field=MainActivity.class.getDeclaredField("webView");field.setAccessible(true);WebView view=(WebView)field.get(this);if(view==null)throw new IllegalStateException("QA_UI_WEBVIEW_MISSING");session.view=view;
                // This is still the onCreate main-thread turn. Cancel the initial navigation
                // before yielding, then use a fresh origin so drafts cannot touch main-origin storage.
                view.stopLoading();view.addJavascriptInterface(session.bridge,"QABusinessData");
                view.setWebViewClient(new WebViewClient(){
                    @Override public boolean shouldOverrideUrlLoading(WebView current,WebResourceRequest request){return !isQaAsset(request.getUrl());}
                    @Override public WebResourceResponse shouldInterceptRequest(WebView current,WebResourceRequest request){
                        Uri uri=request.getUrl();if(!isQaAsset(uri)){session.deniedResources.incrementAndGet();return response(403,"text/plain",new byte[0]);}
                        String name=uri.getPath();if(name==null||!name.matches("/[A-Za-z0-9_./-]+")||name.contains(".."))return response(404,"text/plain",new byte[0]);
                        try{return new WebResourceResponse(mime(name),mime(name).startsWith("text/")||name.endsWith(".js")||name.endsWith(".json")?"UTF-8":null,getAssets().open(name.substring(1)));}catch(IOException missing){return response(404,"text/plain",new byte[0]);}
                    }
                    @Override public void onPageFinished(WebView current,String url){if(!url.equals("https://"+session.host+"/mobile.html"))return;try{current.evaluateJavascript(facadeScript(),null);}catch(Throwable error){session.startupFailure.set(error);}}
                    private boolean isQaAsset(Uri uri){return uri!=null&&"https".equals(uri.getScheme())&&session.host.equals(uri.getHost());}
                });
                view.loadUrl("https://"+session.host+"/mobile.html");
            }catch(Throwable error){session.startupFailure.set(error);}
        }
        @Override protected void onDestroy(){
            try{if(session!=null&&session.view!=null){session.view.stopLoading();session.view.removeJavascriptInterface("QABusinessData");session.view.removeJavascriptInterface("AndroidData");session.view.destroy();}Field field=MainActivity.class.getDeclaredField("store");field.setAccessible(true);PixelLocalStore local=(PixelLocalStore)field.get(this);if(local!=null)local.close();}catch(Throwable error){if(session!=null)session.startupFailure.compareAndSet(null,error);}finally{super.onDestroy();if(session!=null)session.destroyed.countDown();}
        }
    }
    private static WebResourceResponse response(int status,String mime,byte[] bytes){return new WebResourceResponse(mime,"UTF-8",status,status==403?"Forbidden":"Not Found",Collections.emptyMap(),new ByteArrayInputStream(bytes));}
    private static String mime(String name){return name.endsWith(".html")?"text/html":name.endsWith(".js")?"application/javascript":name.endsWith(".json")?"application/json":name.endsWith(".css")?"text/css":name.endsWith(".png")?"image/png":name.endsWith(".svg")?"image/svg+xml":name.endsWith(".jpg")||name.endsWith(".jpeg")?"image/jpeg":name.endsWith(".webp")?"image/webp":"application/octet-stream";}
    private static String facadeScript()throws Exception {
        ArrayList<String> methods=new ArrayList<>();for(Method method:BusinessDataBridge.class.getDeclaredMethods())if(method.isAnnotationPresent(JavascriptInterface.class))methods.add(method.getName());Collections.sort(methods);if(methods.size()!=36)throw new IllegalStateException("QA_UI_BRIDGE_CONTRACT_CHANGED");
        return "(()=>{if(window.qaRealBusinessReady)return;const original=window.AndroidData,qa=window.QABusinessData,facade={},methods="+new JSONArray(methods)+";window.qaBusinessCalls=[];window.qaSavedInvoiceInputIds=[];window.qaBusinessLastErrorCode='';window.qaPlatformBlocked=0;window.qaRuntimeErrors=0;addEventListener('error',()=>qaRuntimeErrors++);addEventListener('unhandledrejection',()=>qaRuntimeErrors++);for(const name of Object.keys(original)){if(typeof original[name]!=='function')continue;facade[name]=()=>{qaPlatformBlocked++;throw Error('QA_PLATFORM_MUTATION_BLOCKED');};}for(const name of ['getAppInfo','getSyncStatus','getPixelTunnelStatus','consumePlanningOpenContext','consumePlanningOpen'])if(typeof original[name]==='function')facade[name]=(...args)=>original[name](...args);for(const name of methods){if(typeof qa[name]!=='function')throw Error('QA_BUSINESS_METHOD_MISSING');facade[name]=(...args)=>{qaBusinessCalls.push(name==='ownerCall'?name+':'+args[0]:name);if(name==='saveInvoice')qaSavedInvoiceInputIds.push(JSON.parse(args[0]).id||'');const result=qa[name](...args);if(name==='ownerCall'){try{const parsed=JSON.parse(result);if(!parsed.ok)qaBusinessLastErrorCode=parsed.error?.code||'QA_OWNER_REFUSED';}catch(_){qaBusinessLastErrorCode='QA_OWNER_INVALID_JSON';}}return result;};}window.AndroidData=facade;window.qaBusinessMethodCount=methods.length;load();openPage('home');TodayUI?.invalidate();LocalInvoiceUI?.ready();window.qaRealBusinessReady=true;return true;})()";
    }

