    private static String js(PixelMcpInstrumentation test,WebView view,String expression)throws Exception{return ReleaseLifecycleProbe.js(test,view,expression);}
    private static void expect(PixelMcpInstrumentation test,WebView view,String label,String condition)throws Exception {
        long end=SystemClock.elapsedRealtime()+30000;while(SystemClock.elapsedRealtime()<end){Session current=active;if(current!=null&&current.startupFailure.get()!=null)throw new AssertionError("QA_UI_STARTUP_"+current.startupFailure.get().getClass().getSimpleName());if("true".equals(js(test,view,"(()=>{try{return !!("+condition+");}catch(_){return false;}})()")))return;SystemClock.sleep(100);}String code=js(test,view,"String(window.qaBusinessLastErrorCode||'NO_BUSINESS_ERROR_CODE')");throw new AssertionError("QA_UI_"+label+"_"+code.replaceAll("[^A-Z0-9_\"]",""));
    }
    private static void action(PixelMcpInstrumentation test,WebView view,String label,String body)throws Exception {String result=js(test,view,"(()=>{"+body+";return true;})()");if(!"true".equals(result))throw new AssertionError("QA_UI_ACTION_"+label);}
    private static String clickScript(String selector){return "const target=document.querySelector("+JSONObject.quote(selector)+");if(!target||target.disabled||target.getBoundingClientRect().height<1)throw Error('QA_UI_CONTROL_UNAVAILABLE');target.scrollIntoView({block:'center'});target.click();";}
